const HTML_B64 = "";
const CATALOG_B64 = "";
const PRICE = 0.042;
const WINDOW_MS = 60 * 60 * 1000;
const LIMIT = 20;
const rate = new Map();
let totalUsd = 0, totalInstructions = 0, totalRequests = 0;

function json(data, status=200) { return new Response(JSON.stringify(data), {status, headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store"}}); }
function ndjson(events) { return new Response(events.map(e=>JSON.stringify(e)).join("\n")+"\n", {headers:{"content-type":"application/x-ndjson; charset=utf-8","cache-control":"no-store"}}); }
function decode(b64) { return Uint8Array.from(atob(b64), c=>c.charCodeAt(0)); }
function initial(data) { return Object.fromEntries(data.devices.map(d=>[d.id,Object.fromEntries(d.capabilities.map(c=>[c.key,c.value]))])); }
function choice(instructions, criteria) { return {type:"choice", instructions, criteria}; }
async function ask(env, state, questions) {
  const start=Date.now();
  const response=await fetch("https://api.typesafe.ai/v1/systemone", {method:"POST",headers:{authorization:`Bearer ${env.JEV_API_KEY}`,"content-type":"application/json",accept:"application/json"},body:JSON.stringify({state,model:"jev-latest",questions})});
  if(!response.ok) throw new Error(`Jev HTTP ${response.status}: ${(await response.text()).slice(0,500)}`);
  const data=await response.json();
  const usage=data.usage||{}, input=Number(usage.input_tokens||0), output=Number(usage.output_tokens||0), cost=input*PRICE/1e6;
  totalUsd+=cost; totalRequests++;
  return {data,ms:Date.now()-start,costs:{request_usd:cost,instruction_usd:cost,input_tokens:input,output_tokens:output,request_count:totalRequests,instruction_count:totalInstructions,cumulative_usd:totalUsd,average_per_instruction_usd:totalInstructions?totalUsd/totalInstructions:0,input_price_per_million_usd:PRICE,pricing_basis:"public_input_token_rate"}};
}
const INTENTS={home_query:"查询智能家居设备、状态、当前数值或设备清单，不改变状态",home_control:"立即控制智能家居设备",ai_question:"向豆包大模型咨询知识或闲聊",scheduled_control:"稍后或周期性控制智能家居",music:"搜索或播放音乐、歌曲或歌手",unclear:"无关、信息不足或无法归类"};
const TERMS={power:["开","关","启动","关闭","打开","开启"],brightness:["亮度","调亮","调暗","变亮","变暗"],color_temperature:["色温","暖白","冷白"],hue:["颜色","色彩","彩色"],mode:["制冷","制热","暖风","冷风","模式","除湿"],target_temperature:["温度","度","℃","摄氏"],fan_speed:["风速","风量"],motion:["摇头","摆头"],position:["窗帘","开合","拉开","合上"],playback:["播放","暂停","继续播放","停止播放"],volume:["音量","声音大小"],target_humidity:["湿度"],level:["档位","强度"],source:["输入源","信号源"],speed:["转速","速度"],oscillation:["摆动"],task:["扫地","清扫","回充"],suction:["吸力","吸尘"],feed:["喂食","投喂"],fridge_temperature:["冷藏"],freezer_temperature:["冷冻"],program:["程序","洗涤模式","洗衣模式"],seat_temperature:["座圈"],water_temperature:["水温"],flush:["冲水"],light:["照明","灯光"]};
async function process(env, body, data, ip) {
  const text=body.text.trim(), events=[], rid=crypto.randomUUID().slice(0,8); totalInstructions++;
  const log=message=>events.push({kind:"log",level:"info",message:`[${rid}] ${message}`});
  log(`收到输入：${text}`); log("第一阶段：请求 Jev 判断业务类别…");
  const q1={intent:choice("这条用户请求最主要属于哪类？",INTENTS)};
  events.push({kind:"debug",label:"第一阶段请求（无密钥）",data:{state:{user_text:text},model:"jev-latest",questions:q1}});
  let first;
  try { first=await ask(env,{user_text:text},q1); } catch(e) { events.push({kind:"error",message:String(e.message||e)}); return events; }
  const a1=first.data.answers?.intent||{}, intent=a1.choice||"unclear";
  events.push({kind:"decision",stage:1,intent,confidence:a1.confidence,probabilities:a1.probabilities||{},model:first.data.model||"jev-latest",usage:first.data.usage||{},ms:first.ms,costs:first.costs});
  events.push({kind:"debug",label:"第一阶段原始响应",data:first.data});
  if(intent!=="home_control") { const labels={home_query:"智能家居查询",ai_question:"豆包 AI 问答",scheduled_control:"定时控制",music:"音乐播放",unclear:"无法确定"}; events.push({kind:"result",status:"routed",text:`Jev 判定为「${labels[intent]||intent}」。此演示仅实现智能家居控制，模拟设备状态未改变。`}); return events; }
  if(Number(a1.confidence)<Number(body.threshold??0.35)) { events.push({kind:"result",status:"clarify",text:"业务分类置信度较低，已停止执行。"}); return events; }
  if(["所有","全部","全屋","整个家","每个","各个","都关","全关"].some(t=>text.includes(t))) { events.push({kind:"result",status:"clarify",text:"当前体验仅支持单设备控制；为避免只执行群组命令的一部分，未执行。"}); return events; }
  const rooms=data.rooms.map(r=>r.name), explicit=rooms.find(n=>text.includes(n)), roomAliases=[["我的卧室","主卧"],["卧室","主卧"],["大厅","客厅"]], alias=roomAliases.find(([a])=>text.includes(a))?.[1], room=explicit||alias||(rooms.includes(body.room)?body.room:null), type=body.device_type;
  const candidates=data.devices.filter(d=>d.controllable!==false&&(!room||d.room===room)&&(!type||d.type===type));
  const ids=Object.fromEntries(candidates.map(d=>[d.id,`${d.room} ${d.type} ${d.name} ${d.capabilities.filter(c=>c.kind==="write").map(c=>c.label).join("、")}`])); ids.none="没有候选设备适合该指令，或用户没有指定可确定的设备。";
  const nums=[...new Set(text.match(/(?<![0-9.])-?\d+(?:\.\d+)?/g)||[])], reqKeys=Object.entries(TERMS).filter(([,words])=>words.some(w=>text.includes(w))).map(([k])=>k);
  const capDefs={}; for(const d of candidates) for(const c of d.capabilities) if(c.kind==="write"&&reqKeys.includes(c.key)) (capDefs[c.key]??={label:c.label,caps:{}}).caps[d.id]=c;
  const questions={device:choice(`Which single device is the user asking to control? Respect explicit room ${room||"unspecified"} and selected type ${type||"automatic"}. Choose only a supplied candidate.`,ids)};
  for(const [key,spec] of Object.entries(capDefs)) { const vals={no_change:"用户没有要求更改此项"}, enums={}; for(const cap of Object.values(spec.caps)) for(const [v,label] of Object.entries(cap.values||{})) (enums[v]??=new Set()).add(String(label)); if(Object.keys(enums).length) for(const [v,set] of Object.entries(enums)) vals[v]=[...set].join(" / "); else nums.forEach((n,i)=>vals[`n${i}`]=`原文数值 ${n}`); questions[`set_${key}`]=choice(`Does the user explicitly ask to set ${spec.label}? Choose the exact value or no_change.`,vals); }
  const state=Object.fromEntries(data.devices.map(d=>[d.id,{...Object.fromEntries(d.capabilities.map(c=>[c.key,c.value])),...(body.device_states?.[d.id]||{})}]));
  events.push({kind:"log",level:"info",message:`第二阶段：并行判断设备及 ${Object.keys(capDefs).length} 项候选可写能力…`});
  events.push({kind:"debug",label:"第二阶段请求（无密钥）",data:{state:{user_text:text,room_hint:room,numeric_candidates:nums},model:"jev-latest",questions}});
  let second;
  try { second=await ask(env,{user_text:text,room_hint:room,numeric_candidates:nums},questions); } catch(e) { events.push({kind:"error",message:String(e.message||e)}); return events; }
  second.costs.instruction_usd=first.costs.request_usd+second.costs.request_usd;
  const answers=second.data.answers||{}, da=answers.device||{}, did=da.choice||"none", operations=[];
  for(const [key,spec] of Object.entries(capDefs)) { const ans=answers[`set_${key}`]||{}, selected=ans.choice; if(!selected||selected==="no_change") continue; const cap=spec.caps[did]; if(!cap||Number(ans.confidence)<Number(body.threshold??0.35)) continue; let value=selected; if(cap.values) { if(!Object.prototype.hasOwnProperty.call(cap.values,selected)) continue; } else { const m=/^n(\d+)$/.exec(selected); if(!m||!nums[Number(m[1])]) continue; value=Number(nums[Number(m[1])]); if(value<cap.min||value>cap.max||Math.abs((value-cap.min)/cap.step-Math.round((value-cap.min)/cap.step))>1e-6) continue; }
    state[did][key]=value; operations.push({key,label:cap.label,value,unit:cap.unit||"",confidence:ans.confidence,probabilities:ans.probabilities||{}});
  }
  events.push({kind:"decision",stage:2,device:did,device_name:data.devices.find(d=>d.id===did)?.name,device_confidence:da.confidence,device_probabilities:da.probabilities||{},operations,model:second.data.model||"jev-latest",usage:second.data.usage||{},ms:second.ms,costs:second.costs});
  events.push({kind:"debug",label:"第二阶段原始响应",data:second.data});
  if(!data.devices.some(d=>d.id===did)) { events.push({kind:"result",status:"clarify",text:"Jev 未选出有效的单个设备，未执行。"}); return events; }
  if(Number(da.confidence)<Number(body.threshold??0.35)) { events.push({kind:"result",status:"clarify",text:"设备选择置信度较低，未执行。请说明房间或设备名称。"}); return events; }
  if(!operations.length) { events.push({kind:"result",status:"clarify",text:`识别到目标设备 ${data.devices.find(d=>d.id===did).name}，但没有可验证的控制参数；未执行。`}); return events; }
  events.push({kind:"execute",status:"success",device_id:did,device_name:data.devices.find(d=>d.id===did).name,room:data.devices.find(d=>d.id===did).room,before:body.device_states?.[did]||initial(data)[did],after:state[did],operations});
  events.push({kind:"result",status:"success",text:"已更新模拟设备状态。"}); return events;
}

export default { async fetch(request, env) {
  const url=new URL(request.url), data=JSON.parse(new TextDecoder().decode(decode(CATALOG_B64)));
  if(request.method==="GET"&&(url.pathname==="/"||url.pathname==="/index.html")) return new Response(decode(HTML_B64),{headers:{"content-type":"text/html; charset=utf-8","cache-control":"no-store"}});
  if(request.method==="GET"&&url.pathname==="/mijia-100-devices.json") return new Response(decode(CATALOG_B64),{headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store"}});
  if(request.method==="GET"&&url.pathname==="/api/state") return json({states:initial(data),devices:data.devices});
  if(request.method==="GET"&&url.pathname==="/api/costs") return json({summary:{request_count:totalRequests,instruction_count:totalInstructions,cumulative_usd:totalUsd,average_per_instruction_usd:totalInstructions?totalUsd/totalInstructions:0},recent_requests:[]});
  if(request.method!=="POST"||!["/api/process","/api/reset"].includes(url.pathname)) return new Response("Not found",{status:404});
  const ip=request.headers.get("cf-connecting-ip")||"unknown", now=Date.now(), times=(rate.get(ip)||[]).filter(t=>now-t<WINDOW_MS);
  if(times.length>=LIMIT) return json({error:"此体验链接每个 IP 每小时最多提交 20 次，请稍后再试。"},429); times.push(now); rate.set(ip,times);
  let body; try { body=await request.json(); } catch { return json({error:"请求 JSON 无效"},400); }
  if(url.pathname==="/api/reset") return json({ok:true,states:initial(data)});
  if(typeof body.text!=="string"||!body.text.trim()||body.text.length>500) return json({error:"请输入 1 到 500 字的文本"},400);
  if(env.JEV_API_KEY==null) return json({error:"服务端尚未配置 Jev API Key"},503);
  return ndjson(await process(env,body,data,ip));
} };
